#!/usr/bin/env python3
"""Offline DFTAgent runner (no API key needed) - DFTAgent enhancement.

One command covers the project rules:
  * works on any ISCAS'85/'89 benchmark (DFF circuits are full-scan converted)
  * reads test patterns from a file (generated by Atalanta, or your own)
  * reports redundant faults (Atalanta-proven) and fault coverage from an
    independent fault simulator

Examples:
  python run_dft.py benchmarks/c432.bench
  python run_dft.py benchmarks/s298.bench
  python run_dft.py benchmarks/c17.bench --patterns my_patterns.txt
"""
import argparse
import json

from tool_atpg import generate_test_vectors
from tool_fault_sim import simulate_patterns
from tool_optimize import optimize_atpg


def main():
    ap = argparse.ArgumentParser(description="Atalanta ATPG + fault simulation for ISCAS'85/'89 .bench circuits")
    ap.add_argument("circuit", help=".bench circuit file (ISCAS'85 or ISCAS'89)")
    ap.add_argument("--patterns", default=None,
                    help="pattern file to grade (default: the patterns Atalanta generates). "
                         "One 0/1 string per line, bit j = scan input j; Atalanta .test format accepted.")
    ap.add_argument("--optimize", action="store_true",
                    help="read each Atalanta report and re-run with larger backtrack limits "
                         "while faults are aborted; keep the best run")
    ap.add_argument("--skip-atpg", action="store_true",
                    help="only fault-simulate --patterns, do not run Atalanta")
    args = ap.parse_args()

    atpg = None
    if args.optimize and not args.skip_atpg:
        print(f"[1/2] Report-driven ATPG optimization on {args.circuit} ...")
        o = json.loads(optimize_atpg(args.circuit))
        if o["status"] != "success":
            print("  optimization failed:", o["message"])
            return 1
        b = o["best"]
        print(f"  BEST: backtrack {b['backtrack_limit']}  ->  coverage {o['baseline_coverage']} % -> "
              f"{o['best_coverage']} %  (+{o['coverage_gain']}),  aborted {o['aborted_before']} -> "
              f"{o['aborted_after']},  redundant {o['redundant_before']} -> {o['redundant_after']},  patterns {b['patterns']}")
        atpg = {"test_vector_file": o["test_vector_file"]}
    elif not args.skip_atpg:
        print(f"[1/2] Atalanta ATPG on {args.circuit} ...")
        atpg = json.loads(generate_test_vectors(args.circuit))
        if atpg["status"] != "success":
            print("  ATPG failed:", atpg["message"])
            if not args.patterns:
                return 1
        else:
            s = atpg["summary"]
            if atpg["scan_converted"]:
                print(f"  sequential circuit: {atpg['dffs_converted']} DFFs full-scan converted")
            print(f"  patterns          : {s.get('patterns_after_compaction')} (after compaction, "
                  f"{s.get('patterns_before_compaction')} before)")
            print(f"  Atalanta coverage : {s.get('fault_coverage')} % of {s.get('collapsed_faults')} collapsed faults")
            print(f"  REDUNDANT faults  : {s.get('redundant_faults')}  (proven by Atalanta)")
            print(f"  aborted faults    : {s.get('aborted_faults')}")
            print(f"  pattern file      : {atpg['test_vector_file']}")

    pat_file = args.patterns or (atpg and atpg.get("test_vector_file"))
    if not pat_file:
        print("no pattern file to simulate (use --patterns)")
        return 1
    label = "your pattern file" if args.patterns else "Atalanta's patterns"
    print(f"[2/2] Independent fault simulation of {label}: {pat_file}")
    sim = json.loads(simulate_patterns(args.circuit, pat_file))
    if sim["status"] != "success":
        print("  fault simulation failed:", sim["message"])
        return 1
    print(f"  patterns read     : {sim['patterns_read']}"
          + (f"  (X bits applied as 0: {sim['x_bits_applied_as_0']})" if sim["x_bits_applied_as_0"] else ""))
    print(f"  fault universe    : {sim['fault_universe']} ({sim['fault_model']})")
    print(f"  detected          : {sim['detected']}   undetected: {sim['undetected']}")
    print(f"  fault coverage    : {sim['fault_coverage']} %")
    if sim["undetected"]:
        print(f"  undetected list   : {sim['undetected_file']}")
        print(f"  first undetected  : {', '.join(sim['undetected_sample'][:8])}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
